import json
from typing import List

def brute_force_max_non_decreasing_length(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    # There are 2^n possible ways to construct nums3.
    # We enumerate all of them.
    max_len = 0

    # Enumerate all 2^n choices using bitmask
    for mask in range(1 << n):
        # Construct nums3 based on the current mask
        nums3 = []
        for i in range(n):
            if (mask >> i) & 1:
                nums3.append(nums2[i])
            else:
                nums3.append(nums1[i])

        # Find the longest non-decreasing subarray in nums3
        current_len = 0
        if n > 0:
            current_len = 1
            for i in range(1, n):
                if nums3[i] >= nums3[i-1]:
                    current_len += 1
                else:
                    if current_len > max_len:
                        max_len = current_len
                    current_len = 1
            if current_len > max_len:
                max_len = current_len

        if max_len == n:
            return n  # Early exit if we found the maximum possible

    return max_len

class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        return brute_force_max_non_decreasing_length(nums1, nums2)

