class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        """
        Brute-force solution: iterate through every integer in [low, high],
        check both conditions directly, and count the beautiful ones.
        This is intentionally simple and correct for very small ranges.
        """
        def is_beautiful(n: int) -> bool:
            s = str(n)
            even_cnt = 0
            odd_cnt = 0
            for ch in s:
                d = int(ch)
                if d % 2 == 0:
                    even_cnt += 1
                else:
                    odd_cnt += 1
            if even_cnt != odd_cnt:
                return False
            if n % k != 0:
                return False
            return True

        count = 0
        for num in range(low, high + 1):
            if is_beautiful(num):
                count += 1
        return count

