import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            a = int(next(iterator))
            b = int(next(iterator))
        except StopIteration:
            break

        # Construct the array: a ones and b twos
        arr = [1] * a + [2] * b
        n = len(arr)

        # If there are no elements, sum is 0 by default? 
        # But constraints say a,b >= 0, and if both 0, array is empty -> sum 0 -> YES.
        # However, problem examples don't show 0 0 case. We'll handle it naturally.
        if n == 0:
            results.append("YES")
            continue

        # Brute force: try all 2^n sign combinations
        # Each element can be +1 or -1 multiplier
        found = False
        # Iterate from 0 to 2^n - 1
        for mask in range(1 << n):
            total = 0
            for i in range(n):
                if (mask >> i) & 1:
                    total += arr[i]
                else:
                    total -= arr[i]
            if total == 0:
                found = True
                break

        if found:
            results.append("YES")
        else:
            results.append("NO")

    # Print all results
    for res in results:
        print(res)

