def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        fj_combo = [int(next(iterator)) for _ in range(3)]
        master_combo = [int(next(iterator)) for _ in range(3)]
    except StopIteration:
        return

    # Helper to check if a dial value is within tolerance of a target value
    # The dials are circular 1..N. Distance is min(abs(a-b), N-abs(a-b))
    def is_close(val, target, n, tolerance=2):
        diff = abs(val - target)
        circular_diff = n - diff
        dist = min(diff, circular_diff)
        return dist <= tolerance

    # Helper to check if a setting opens the lock
    def opens_lock(setting, fj, master, n):
        # Check if close to Farmer John's combination
        close_to_fj = True
        for i in range(3):
            if not is_close(setting[i], fj[i], n):
                close_to_fj = False
                break

        if close_to_fj:
            return True

        # Check if close to Master combination
        close_to_master = True
        for i in range(3):
            if not is_close(setting[i], master[i], n):
                close_to_master = False
                break

        return close_to_master

    count = 0
    # Brute force: iterate through all possible settings (1..N for each of 3 dials)
    # Since N <= 100, N^3 = 1,000,000 which is small enough for brute force.
    # The problem asks for a brute-force solution intended for small inputs, 
    # and this is the most direct enumeration.
    for d1 in range(1, N + 1):
        for d2 in range(1, N + 1):
            for d3 in range(1, N + 1):
                if opens_lock([d1, d2, d3], fj_combo, master_combo, N):
                    count += 1

    print(count)

