def is_palindrome(arr: List[int]) -> bool:
    return arr == arr[::-1]

def count_flips_to_make_rows_palindromic(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])
    flips = 0
    for r in range(m):
        row = grid[r]
        for c in range(n // 2):
            if row[c] != row[n - 1 - c]:
                flips += 1
    return flips

def count_flips_to_make_cols_palindromic(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])
    flips = 0
    for c in range(n):
        col = [grid[r][c] for r in range(m)]
        for r in range(m // 2):
            if col[r] != col[m - 1 - r]:
                flips += 1
    return flips

def minFlips(grid: List[List[int]]) -> int:
    # Option 1: make all rows palindromic
    flips_rows = count_flips_to_make_rows_palindromic(grid)
    # Option 2: make all columns palindromic
    flips_cols = count_flips_to_make_cols_palindromic(grid)
    return min(flips_rows, flips_cols)

