import sys

def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
        D = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        B = []
        for _ in range(M):
            B.append(int(next(iterator)))
    except StopIteration:
        return

    max_sum = -1

    # Brute-force: Check every possible pair (a, b) where a is from A and b is from B
    for a_val in A:
        for b_val in B:
            diff = abs(a_val - b_val)
            if diff <= D:
                current_sum = a_val + b_val
                if current_sum > max_sum:
                    max_sum = current_sum

    print(max_sum)

