import json
from typing import *

def is_vowel(c: str) -> bool:
    return c in "aeiou"

def count_vowels(sub: str) -> int:
    return sum(1 for c in sub if is_vowel(c))

def can_alice_move(s: str) -> bool:
    # Alice needs a non-empty substring with odd number of vowels
    n = len(s)
    for i in range(n):
        for j in range(i+1, n+1):
            sub = s[i:j]
            if count_vowels(sub) % 2 == 1:
                return True
    return False

def can_bob_move(s: str) -> bool:
    # Bob needs a non-empty substring with even number of vowels
    n = len(s)
    for i in range(n):
        for j in range(i+1, n+1):
            sub = s[i:j]
            if count_vowels(sub) % 2 == 0:
                return True
    return False

def simulate_game(s: str, turn: int) -> bool:
    """
    Simulates the game from state `s` with `turn` indicating whose turn it is.
    turn = 0 -> Alice's turn
    turn = 1 -> Bob's turn
    Returns True if Alice wins from this state assuming optimal play.
    This is a brute-force minimax with memoization over string states.
    """
    # Base case: if current player cannot move, they lose.
    # So if it's Alice's turn and she can't move, she loses -> return False.
    # If it's Bob's turn and he can't move, he loses -> Alice wins -> return True.
    if turn == 0:
        if not can_alice_move(s):
            return False
    else:
        if not can_bob_move(s):
            return True

    # Memoization key: (s, turn)
    memo_key = (s, turn)
    if memo_key in memo:
        return memo[memo_key]

    if turn == 0:
        # Alice's turn: she wins if there exists a move leading to a state where Alice wins
        # after Bob plays optimally.
        n = len(s)
        for i in range(n):
            for j in range(i+1, n+1):
                sub = s[i:j]
                if count_vowels(sub) % 2 == 1:
                    new_s = s[:i] + s[j:]
                    # After Alice moves, it's Bob's turn
                    if simulate_game(new_s, 1):
                        memo[memo_key] = True
                        return True
        # If no move leads to Alice winning, she loses
        memo[memo_key] = False
        return False
    else:
        # Bob's turn: he wins if there exists a move leading to a state where Alice loses
        # (i.e., Bob wins) after Alice plays optimally.
        # But we are returning whether Alice wins, so Bob will try to make Alice lose.
        n = len(s)
        for i in range(n):
            for j in range(i+1, n+1):
                sub = s[i:j]
                if count_vowels(sub) % 2 == 0:
                    new_s = s[:i] + s[j:]
                    # After Bob moves, it's Alice's turn
                    if not simulate_game(new_s, 0):
                        # Bob can force Alice to lose, so from this state Alice loses
                        memo[memo_key] = False
                        return False
        # If all Bob's moves lead to Alice winning, then Alice wins
        memo[memo_key] = True
        return True

memo = {}

def doesAliceWin_bruteforce(s: str) -> bool:
    global memo
    memo = {}
    return simulate_game(s, 0)

class Solution:
    def doesAliceWin(self, s: str) -> bool:
        return doesAliceWin_bruteforce(s)

