def solve():
    # Read the 3x3 board from standard input
    board = []
    try:
        for _ in range(3):
            line = sys.stdin.readline().strip()
            if not line:
                break
            board.append(list(line))
    except Exception:
        pass

    if len(board) != 3:
        # Should not happen based on problem constraints, but safe fallback
        print(0)
        print(0)
        return

    # Ensure each row has exactly 3 characters
    for i in range(3):
        if len(board[i]) < 3:
            # Pad or handle error if necessary, but problem guarantees 3 chars
            board[i].extend([''] * (3 - len(board[i])))

    # List of all 8 winning lines (rows, columns, diagonals)
    lines = []
    # Rows
    for r in range(3):
        lines.append([(r, c) for c in range(3)])
    # Columns
    for c in range(3):
        lines.append([(r, c) for r in range(3)])
    # Diagonals
    lines.append([(0, 0), (1, 1), (2, 2)])
    lines.append([(0, 2), (1, 1), (2, 0)])

    # Collect all unique characters present on the board
    all_chars = set()
    for r in range(3):
        for c in range(3):
            all_chars.add(board[r][c])

    # Count individual winners
    individual_winners = set()
    for char in all_chars:
        for line in lines:
            # Check if this line consists ONLY of this character
            is_win = True
            for r, c in line:
                if board[r][c] != char:
                    is_win = False
                    break
            if is_win:
                individual_winners.add(char)
                break  # No need to check other lines for this char

    # Count two-cow team winners
    team_winners = set()
    # Generate all unique pairs of characters from the board
    chars_list = sorted(list(all_chars))
    n = len(chars_list)
    for i in range(n):
        for j in range(i + 1, n):
            cow1 = chars_list[i]
            cow2 = chars_list[j]
            # Check if this pair can win
            for line in lines:
                # Check if line contains ONLY cow1 or cow2
                # AND contains BOTH at least once
                contains_cow1 = False
                contains_cow2 = False
                is_valid_line = True
                for r, c in line:
                    cell = board[r][c]
                    if cell == cow1:
                        contains_cow1 = True
                    elif cell == cow2:
                        contains_cow2 = True
                    else:
                        # Contains a character not in the team
                        is_valid_line = False
                        break
                if is_valid_line and contains_cow1 and contains_cow2:
                    # This team wins
                    team_winners.add((cow1, cow2))
                    break  # No need to check other lines for this pair

    # Output results
    print(len(individual_winners))
    print(len(team_winners))

