class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Enumerate all possible subarrays [i, j]
        for i in range(n):
            for j in range(i, n):
                # Extract the subarray
                sub = nums[i:j+1]

                # Check the condition: for every pair in the subarray,
                # the absolute difference must be <= 2
                valid = True
                for a in range(len(sub)):
                    for b in range(a + 1, len(sub)):
                        if abs(sub[a] - sub[b]) > 2:
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    count += 1

        return count

