def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().strip().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
    except StopIteration:
        return

    shifts = []
    for _ in range(n):
        start = int(next(iterator))
        end = int(next(iterator))
        shifts.append((start, end))

    # The pool is open from t=0 to t=1000.
    # We can model time as discrete units [t, t+1).
    # Since the max time is 1000, we can simply check every integer unit from 0 to 999.
    # A shift [start, end] covers units start, start+1, ..., end-1.

    max_covered = 0

    # Brute force: try firing each lifeguard one by one
    for i in range(n):
        # Create a list of shifts excluding the i-th lifeguard
        current_shifts = []
        for j in range(n):
            if i == j:
                continue
            current_shifts.append(shifts[j])

        # Calculate covered time for this configuration
        covered_units = set()
        for (s, e) in current_shifts:
            # Add all integer units covered by this shift
            for t in range(s, e):
                covered_units.add(t)

        current_total = len(covered_units)
        if current_total > max_covered:
            max_covered = current_total

    print(max_covered)

