def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    # Store cows as a set of tuples for O(1) lookup
    cows = set()

    # Helper function to check if a cow at (x, y) is comfortable
    # A cow is comfortable if it has exactly 3 neighbors (up, down, left, right)
    def is_comfortable(x, y):
        neighbors = 0
        if (x + 1, y) in cows:
            neighbors += 1
        if (x - 1, y) in cows:
            neighbors += 1
        if (x, y + 1) in cows:
            neighbors += 1
        if (x, y - 1) in cows:
            neighbors += 1
        return neighbors == 3

    # Process each cow addition one by one
    for i in range(N):
        try:
            x = int(next(iterator))
            y = int(next(iterator))
        except StopIteration:
            break

        # Add the new cow
        cows.add((x, y))

        # Brute-force: Iterate through ALL cows currently on the board
        # and count how many are comfortable.
        # This is O(K) where K is the number of cows added so far.
        # Since we do this for every step, total complexity is O(N^2).
        # For very small N (like N <= 400 in subtasks), this is acceptable.
        # The problem asks for a brute-force solution that is obviously correct.

        count = 0
        for (cx, cy) in cows:
            if is_comfortable(cx, cy):
                count += 1

        print(count)

