class Solution:
    def countInterestingSubarrays(self, nums: List[int], modulo: int, k: int) -> int:
        n = len(nums)
        count = 0

        # Brute-force: enumerate all subarrays [l, r]
        for l in range(n):
            for r in range(l, n):
                # Count indices i in [l, r] such that nums[i] % modulo == k
                cnt = 0
                for i in range(l, r + 1):
                    if nums[i] % modulo == k:
                        cnt += 1
                # Check if cnt % modulo == k
                if cnt % modulo == k:
                    count += 1

        return count

